FROM icustays
WHERE subject_id = @PatientID
ORDER BY intime DESC;

-- Check if the current date falls within the interval of the last stay
IF dbo.DURING(GETDATE(), dbo.TIME_INTERVAL([@LastStayStart], [@LastStayEnd])) = 1
BEGIN
  -- Calculate the duration of stay in days
  SELECT DATEDIFF(day, @LastStayStart, @LastStayEnd) AS DurationOfStayInDays;
END
ELSE
BEGIN
  PRINT 'No stay found for the given patient or current date does not fall within the interval of the last stay.';
END

